import re

from fastapi import Header

_SESSION_RE = re.compile(r"^[A-Za-z0-9-]{8,64}$")


def session_id(x_scout_session: str | None = Header(default=None)) -> str:
    """Anonymous session id generated by the phone. Invalid or missing ids share one 'anonymous' bucket."""
    if x_scout_session and _SESSION_RE.match(x_scout_session):
        return x_scout_session
    return "anonymous"
